float4 amzSample_air(float2 uv) { return float4(amzt_air.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/64.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_dk(uv);if(tex==2) return amzSample_dk2(uv);if(tex==3) return amzSample_air(uv);return float4(0.0); }
uniform float amzp_amount;
uniform float amzp_hazeSrc;
layout(color) uniform half4 amzp_hazeColor;
uniform float amzp_protect;
uniform float amzp_expoComp;
uniform float amzp_refine;
uniform float amzp_showMap;
    float3 unp(float4 s) { return s.a > 0.0001 ? s.rgb / s.a : float3(0.0); }
    void amzRender() {
        float2 uv = amzScreenNorm();
        float amt = clamp(amzp_amount, -1.0, 1.0);
        bool off = abs(amt) < 0.0001 && !(amzp_showMap>0.5);
        if (amzPass == 0) {
            if (off) { amzOutput = float4(0.0); return; }
            float2 cell = 1.0 / (screen.zw/8.0);
            float3 sum = float3(0.0);
            float n = 0.0, dark = 1.0;
            for (int j = 0; j < 4; j++) {
                for (int i = 0; i < 4; i++) {
                    float2 q = uv + ((float2(float(i), float(j)) + 0.5) / 4.0 - 0.5) * cell;
                    float4 s = amzTexture(0, q);
                    if (s.a > 0.5) {
                        float3 u = s.rgb / s.a;
                        sum += u;
                        n += 1.0;
                        dark = min(dark, min(u.r, min(u.g, u.b)));
                    }
                }
            }
            amzOutput = n > 0.0 ? float4(sum / n, dark) : float4(0.0);
            return;
        }
        if (amzPass == 1) {
            if (off) { amzOutput = float4(0.0); return; }
            float2 ratio = ceil((screen.zw/8.0) / (screen.zw/64.0));
            float2 first = floor((uv - 0.5 / (screen.zw/64.0)) * (screen.zw/8.0) + 0.001);
            float best = -1.0;
            float3 col = float3(0.0);
            for (int j = 0; j < 12; j++) {
                if (float(j) >= ratio.y) break;
                for (int i = 0; i < 12; i++) {
                    if (float(i) >= ratio.x) break;
                    float2 idx = first + float2(float(i), float(j));
                    if (idx.x < 0.0 || idx.y < 0.0 || idx.x >= (screen.zw/8.0).x || idx.y >= (screen.zw/8.0).y) continue;
                    float4 s = amzTexture(1, (idx + 0.5) / (screen.zw/8.0));
                    if (s.a > best) { best = s.a; col = s.rgb; }
                }
            }
            amzOutput = float4(col, max(best, 0.0));
            return;
        }
        if (amzPass == 2) {
            if (off || int(amzp_hazeSrc) == 1) { amzOutput = float4(0.0); return; }
            float best = -1.0;
            float3 col = float3(1.0);
            for (int j = 0; j < 64; j++) {
                if (float(j) >= (screen.zw/64.0).y) break;
                for (int i = 0; i < 64; i++) {
                    if (float(i) >= (screen.zw/64.0).x) break;
                    float4 s = amzTexture(2, (float2(float(i), float(j)) + 0.5) / (screen.zw/64.0));
                    if (s.a > best) { best = s.a; col = s.rgb; }
                }
            }
            amzOutput = float4(col, 1.0);
            return;
        }
        float4 src = amzTexture(0, uv);
        if (off || src.a <= 0.0001) { amzOutput = src; return; }
        float3 u = unp(src);
        float3 A = int(amzp_hazeSrc) == 1 ? amzp_hazeColor.rgb : amzTexture(3, float2(0.5)).rgb;
        A = max(A, float3(0.05));
        float2 sz = (screen.zw/8.0);
        float2 c0 = floor(uv * sz);
        float sg = mix(0.35, 0.06, clamp(amzp_refine, 0.0, 1.0));
        float dsum = 0.0, wsum = 0.0;
        for (int j = -1; j <= 1; j++) {
            for (int i = -1; i <= 1; i++) {
                float2 idx = clamp(c0 + float2(float(i), float(j)), float2(0.0), sz - 1.0);
                float4 s = amzTexture(1, (idx + 0.5) / sz);
                float2 dd = (idx + 0.5) - uv * sz;
                float ws = exp(-dot(dd, dd) / 1.5);
                float3 e = u - s.rgb;
                float w = ws * (exp(-dot(e, e) / (2.0 * sg * sg)) + 0.0001);
                dsum += s.a * w;
                wsum += w;
            }
        }
        float dB = dsum / max(wsum, 1e-6);
        float Am = max(dot(A, float3(0.3333)), 0.05);
        float dP = min(u.r / A.r, min(u.g / A.g, u.b / A.b));
        float d = clamp(min(dB / Am, dP), 0.0, 1.0);
        if ((amzp_showMap>0.5)) { amzOutput = float4(float3(d) * src.a, src.a); return; }
        float3 J;
        if (amt >= 0.0) {
            float t = max(1.0 - amt * 0.95 * d, mix(0.05, 0.6, clamp(amzp_protect, 0.0, 1.0)));
            J = (u - A) / t + A;
            J *= 1.0 + clamp(amzp_expoComp, 0.0, 1.0) * (1.0 - t) * 0.8;
        } else {
            J = mix(u, A, -amt * 0.7 * (0.35 + 0.65 * d));
        }
        amzOutput = float4(clamp(J, 0.0, 1.0) * src.a, src.a);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

